import dao.*;import model.*;import util.*;import view.TelaPedidos;
import javax.swing.*;import java.awt.*;import java.awt.event.*;import java.awt.image.BufferedImage;import java.math.BigDecimal;import java.sql.*;import java.nio.file.*;import java.util.concurrent.*;import java.util.function.BooleanSupplier;import javax.imageio.ImageIO;

/** Confere área visível e ações reais; vendas e falhas ficam exclusivamente na base de teste. */
public final class FluxoVendaBalcao {
    private static class TelaTeste extends TelaPedidos {
        volatile int sucessos,avisos,id;TelaTeste(Usuario u){super(u,null);}
        protected boolean confirmarRetirada(Cliente c){return true;}
        protected void vendaConcluida(int pedido){sucessos++;id=pedido;}
        protected void aviso(String texto){avisos++;}
    }
    private static TelaTeste tela;
    public static void main(String[] args)throws Exception {
        Thread limite=new Thread(()->{try{Thread.sleep(100000);}catch(InterruptedException e){return;}System.err.println("Falha: fluxo balcão excedeu limite.");System.exit(1);});limite.setDaemon(true);limite.start();
        boolean somenteLayout=args.length==1 && args[0].equals("--somente-layout");exigir(texto("SELECT current_database()").equals(somenteLayout?"obotbarato":"obotbarato_test"),"Base incorreta para o modo de teste.");
        Usuario admin=new UsuarioDAO().autenticar("admin","admin123");Sessao.iniciar(admin);long pedidosAntes=numero("SELECT COUNT(*) FROM pedidos"),saldoAntes=numero("SELECT SUM(quantidade) FROM estoque");
        if(somenteLayout){
            SwingUtilities.invokeAndWait(()->{tela=new TelaTeste(admin);preparar();layouts();exigir(combo("balcao-produto").getItemCount()>1,"Catálogo vazio.");exigir(combo("balcao-cliente").getItemCount()>1,"Clientes ausentes.");combo("balcao-cliente").setSelectedIndex(1);combo("balcao-produto").setSelectedIndex(1);botao("+ Adicionar").doClick();exigir(tabela().getRowCount()==1,"Adicionar não funciona na base local.");try{imagem("venda-balcao-base-local.png");}catch(Exception e){throw new RuntimeException(e);}tela.dispose();});
            exigir(numero("SELECT COUNT(*) FROM pedidos")==pedidosAntes && numero("SELECT SUM(quantidade) FROM estoque")==saldoAntes,"Verificação visual alterou vendas/estoque.");System.out.println("APROVADO: catálogo/clientes da base local, seleção e inclusão de item visíveis sem sobreposição; vendas e estoque preservados.");Sessao.encerrar();System.exit(0);
        }
        Produto p=new Produto();p.setNome("Produto Balcão Interface");p.setPreco(new BigDecimal("10.25"));p.setIdCategoria(new CategoriaDAO().listar(false).get(0).id());p.setEstoqueInicial(8);p.setAtivo(true);new ProdutoDAO().salvar(p);
        String email="balcaoui"+java.util.UUID.randomUUID().toString().substring(0,8)+"@teste.local";exigir(new ClienteLojaDAO().cadastrar("Cliente Balcão Sem CPF",null,email,"11999990000","Rua de teste, 100","senha12345")==null,"Cadastro falhou.");
        SwingUtilities.invokeAndWait(()->{tela=new TelaTeste(admin);preparar();layouts();exigir(!botao("+ Adicionar").isEnabled() && !botao("Concluir retirada").isEnabled(),"Comandos prematuros habilitados.");for(int i=0;i<combo("balcao-cliente").getItemCount();i++)exigir(!combo("balcao-cliente").getItemAt(i).toString().contains("null"),"Cliente mostra null.");selecionar("balcao-produto",p.getNome());JSpinner sp=encontrar(tela,JSpinner.class,"balcao-quantidade");((JSpinner.DefaultEditor)sp.getEditor()).getTextField().setText("0");botao("+ Adicionar").doClick();exigir(tela.avisos==1 && tabela().getRowCount()==0,"Quantidade inválida entrou no pedido.");((JSpinner.DefaultEditor)sp.getEditor()).getTextField().setText("3");botao("+ Adicionar").doClick();exigir(tabela().getRowCount()==1 && tabela().getValueAt(0,1).equals(3) && tabela().getValueAt(0,3).toString().contains("30,75"),"Quantidade digitada/subtotal incorretos.");exigir(!botao("Concluir retirada").isEnabled(),"Venda sem cliente permitida.");selecionar("balcao-cliente","Cliente Balcão Sem CPF");sp.setValue(1);botao("+ Adicionar").doClick();tabela().setRowSelectionInterval(1,1);botao("Remover Item").doClick();exigir(tabela().getRowCount()==1 && botao("Concluir retirada").isEnabled(),"Remoção/finalização incorretas.");try{imagem("venda-balcao.png");}catch(Exception e){throw new RuntimeException(e);}});
        System.out.println("OK: campos visíveis em três tamanhos, cabeçalho separado, CPF ausente sem null, moeda brasileira e quantidade digitada confirmada.");
        long antesFalha=numero("SELECT COUNT(*) FROM pedidos");sql("CREATE FUNCTION teste_balcao_falha() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'falha proposital'; END $$");sql("CREATE TRIGGER teste_balcao BEFORE INSERT ON pagamentos FOR EACH ROW EXECUTE FUNCTION teste_balcao_falha()");
        try{SwingUtilities.invokeAndWait(()->{botao("Concluir retirada").doClick();botao("Concluir retirada").doClick();exigir(!botao("+ Adicionar").isEnabled(),"Pode adicionar durante gravação.");tela.dispatchEvent(new WindowEvent(tela,WindowEvent.WINDOW_CLOSING));exigir(tela.isDisplayable(),"Fechou durante gravação.");});aguardar(()->tela.avisos==2 && botao("Concluir retirada").isEnabled());exigir(numero("SELECT COUNT(*) FROM pedidos")==antesFalha && new EstoqueDAO().getQuantidade(p.getId())==8 && tela.sucessos==0,"Falha deixou venda/saldo ou sucesso falso.");}
        finally{sql("DROP TRIGGER teste_balcao ON pagamentos");sql("DROP FUNCTION teste_balcao_falha()");}
        System.out.println("OK: falha de pagamento desfaz a venda e estoque, preserva itens na tela e permite tentar novamente.");
        SwingUtilities.invokeAndWait(()->{botao("Concluir retirada").doClick();botao("Concluir retirada").doClick();});aguardar(()->tela.sucessos==1 && !tela.isDisplayable());
        exigir(numero("SELECT COUNT(*) FROM pedidos")==antesFalha+1 && new EstoqueDAO().getQuantidade(p.getId())==5,"Gravou duas vendas ou saldo incorreto.");exigir(texto("SELECT concat(p.origem,':',p.status,':',pg.metodo,':',pg.status,':',p.total) FROM pedidos p JOIN pagamentos pg ON pg.id_pedido=p.id WHERE p.id="+tela.id).equals("balcao:entregue:dinheiro:confirmado:30.75"),"Retirada/pagamento/total incorretos.");
        System.out.println("APROVADO: fluxo Swing de seleção, adicionar/remover, quantidade digitada, layout/redimensionamento, falha/rollback, nova tentativa, confirmação única e baixa de estoque no balcão.");SwingUtilities.invokeAndWait(()->{for(Window w:Window.getWindows())w.dispose();});Sessao.encerrar();System.exit(0);
    }
    private static void layouts(){for(Dimension d:new Dimension[]{new Dimension(780,520),new Dimension(780,600),new Dimension(960,700)}){tela.setSize(d);tela.validate();layout(tela.getContentPane());Component produto=combo("balcao-produto"),cliente=combo("balcao-cliente");visivel(produto);visivel(cliente);visivel(botao("+ Adicionar"));visivel(encontrar(tela,JSpinner.class,"balcao-quantidade"));Rectangle campo=SwingUtilities.convertRectangle(produto.getParent(),produto.getBounds(),tela.getContentPane());Rectangle cabecalho=SwingUtilities.convertRectangle(tabela().getTableHeader().getParent(),tabela().getTableHeader().getBounds(),tela.getContentPane());exigir(cabecalho.y>=campo.y+campo.height,"Tabela sobrepõe seleção de produto.");}tela.setSize(780,600);tela.validate();layout(tela.getContentPane());}
    private static void visivel(Component item){exigir(item.getWidth()>20 && item.getHeight()>=25,"Campo/botão sem tamanho.");Rectangle area=new Rectangle(0,0,item.getWidth(),item.getHeight());for(Container p=item.getParent();p!=null;p=p.getParent()){Rectangle r=SwingUtilities.convertRectangle(item,area,p);exigir(new Rectangle(0,0,p.getWidth(),p.getHeight()).contains(r),"Campo/botão cortado em "+p.getClass().getSimpleName());}}
    private static void preparar(){tela.addNotify();tela.validate();}
    private static JTable tabela(){return encontrar(tela,JTable.class,"balcao-itens");}private static JComboBox<?> combo(String nome){return encontrar(tela,JComboBox.class,nome);}
    private static void selecionar(String nome,String texto){JComboBox<?> c=combo(nome);for(int i=0;i<c.getItemCount();i++)if(c.getItemAt(i).toString().startsWith(texto)){c.setSelectedIndex(i);return;}throw new AssertionError("Opção ausente: "+texto);}
    private static JButton botao(String texto){JButton b=encontrar(tela,JButton.class,texto);if(b==null)throw new AssertionError("Botão ausente: "+texto);return b;}
    private static <T extends Component>T encontrar(Container c,Class<T> tipo,String nome){for(Component f:c.getComponents()){if(tipo.isInstance(f) && (nome.equals(f.getName()) || f instanceof AbstractButton && nome.equals(((AbstractButton)f).getText())))return tipo.cast(f);if(f instanceof Container){T r=encontrar((Container)f,tipo,nome);if(r!=null)return r;}}return null;}
    private static void aguardar(BooleanSupplier b)throws Exception{CountDownLatch l=new CountDownLatch(1);SwingUtilities.invokeAndWait(()->{javax.swing.Timer t=new javax.swing.Timer(100,null);t.addActionListener(e->{if(b.getAsBoolean()){t.stop();l.countDown();}});t.start();});exigir(l.await(30,TimeUnit.SECONDS),"Operação da interface não concluiu.");}
    private static void layout(Container c){c.doLayout();for(Component f:c.getComponents())if(f instanceof Container)layout((Container)f);}
    private static void imagem(String nome)throws Exception{Container p=tela.getContentPane();layout(p);BufferedImage b=new BufferedImage(p.getWidth(),p.getHeight(),BufferedImage.TYPE_INT_RGB);Graphics2D g=b.createGraphics();try{p.printAll(g);}finally{g.dispose();}ImageIO.write(b,"png",Path.of("docs/validacao-ui",nome).toFile());}
    private static String texto(String sql)throws SQLException{try(Connection c=ConexaoBanco.getConexao();Statement s=c.createStatement();ResultSet r=s.executeQuery(sql)){r.next();return r.getString(1);}}
    private static long numero(String sql)throws SQLException{return Long.parseLong(texto(sql));}private static void sql(String sql)throws SQLException{try(Connection c=ConexaoBanco.getConexao();Statement s=c.createStatement()){s.execute(sql);}}
    private static void exigir(boolean b,String texto){if(!b)throw new AssertionError(texto);}
}
